'use strict';
// 保護者提供のEllis音声。各段のMP3を無音部分で区切って使います。
const BundledChants=(()=>{
 const recordings={"1":{"encoded":"","ranges":[[0.23,1.97],[2.98,4.28],[5.22,6.86],[7.84,9.18],[10.21,11.54],[12.53,14.11],[15.02,16.55],[17.5,19.12],[19.99,21.746]]},"2":{"encoded":"","ranges":[[0.2,1.47],[2.48,3.71],[4.6,5.97],[6.93,8.17],[9.11,10.16],[10.93,12.23],[12.88,14.14],[14.91,16.31],[17,18.602]]}};
 const blobs={};
 function clip(key){const match=/^chant:([1-9])-([1-9])$/.exec(key);if(!match)return null;const row=recordings[match[1]];if(!row)return null;blobs[match[1]] ||= new Blob([Uint8Array.from(atob(row.encoded),c=>c.charCodeAt(0))],{type:'audio/mpeg'});const [start,end]=row.ranges[Number(match[2])-1];return {blob:blobs[match[1]],start,duration:end-start};}
 return {clip};
})();
